package app.space.notes;
import android.content.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import app.space.notes.domain.*;
import app.space.notes.runtime.*;
import org.junit.*;
import org.junit.runner.RunWith;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;
/** Real AtomicFile/codec restart tests. Never points at a user's files. */
@RunWith(AndroidJUnit4.class)
public class HistoryRecoveryTest {
 private File root;private Context context;
 @Before public void setup(){Context target=InstrumentationRegistry.getInstrumentation().getTargetContext();root=new File(target.getCacheDir(),"history-"+UUID.randomUUID());assertTrue(root.mkdirs());context=new ContextWrapper(target){public File getFilesDir(){return root;}public SharedPreferences getSharedPreferences(String name,int mode){return target.getSharedPreferences(root.getName()+name,mode);}};new NotesRepository(context);}
 private void remove(File f){File[] all=f.listFiles();if(all!=null)for(File child:all)remove(child);assertTrue(!f.exists() || f.delete());}
 @After public void cleanup(){context.deleteSharedPreferences(root.getName()+"mynotes-storage-v1");remove(root);}
 private Note note(){Note n=Note.create(1).edit("Original","Keep words 漢😀",2);return n.withContent(DocumentContent.fromLegacy(n),3);}
 private File file(){return new File(root,"notes-library/edit-history-v1.json");}
 private void save(PersistentHistoryStore store,Note current,DocumentHistory h)throws Exception{store.save(Arrays.asList(new PersistentHistoryStore.Entry(current,h.snapshot())));}
 @Test public void undoAndRedoSurviveIndependentStoreInstancesWithRichContentAndCursor()throws Exception{Note a=note(),b=a.title("Edited",4),c=b.withContent(b.content.withWritingLines(true),5);DocumentHistory h=new DocumentHistory();h.rememberCursor(a,new DocumentHistory.Cursor("title",1,3));h.record(a,b,null,1);h.record(b,c,null,2);PersistentHistoryStore store=new PersistentHistoryStore(context);save(store,c,h);DocumentHistory loaded=new PersistentHistoryStore(context).load(Arrays.asList(c)).get(c.id);assertNotNull(loaded);Note previous=loaded.undo(c);assertTrue(NoteMerge.same(b,previous));save(store,previous,loaded);DocumentHistory restarted=new PersistentHistoryStore(context).load(Arrays.asList(previous)).get(c.id);assertTrue(restarted.canRedo());assertTrue(NoteMerge.same(c,restarted.redo(previous)));Note back=restarted.undo(c);back=restarted.undo(back);assertTrue(NoteMerge.same(a,back));assertEquals(3,restarted.cursor(back).focus);}
 @Test public void staleAnchorAndDeletedNotesNeverOverwriteOrResurrectCurrentData()throws Exception{Note a=note(),b=a.title("New",4);DocumentHistory h=new DocumentHistory();h.record(a,b,null,1);PersistentHistoryStore store=new PersistentHistoryStore(context);save(store,b,h);Note newer=b.title("External newer",9);NotesRepository repo=new NotesRepository(context);repo.save(Arrays.asList(newer));byte[] before=DocumentCodec.encode(repo.load());assertTrue(new PersistentHistoryStore(context).load(Arrays.asList(newer)).isEmpty());assertTrue(new PersistentHistoryStore(context).load(Collections.emptyList()).isEmpty());assertArrayEquals(before,DocumentCodec.encode(repo.load()));}
 @Test public void corruptHistoryIsRetainedAndBlockedUntilExplicitResetWithoutTouchingNotes()throws Exception{Note a=note();NotesRepository repo=new NotesRepository(context);repo.save(Arrays.asList(a));byte[] before=DocumentCodec.encode(repo.load());byte[] broken="{\"version\":1,\"payload\":\"{}\",\"sha256\":\"bad\"}".getBytes("UTF-8");java.nio.file.Files.write(file().toPath(),broken);PersistentHistoryStore store=new PersistentHistoryStore(context);assertTrue(store.load(Arrays.asList(a)).isEmpty());assertNotNull(store.notice());try{store.save(Collections.emptyList());fail("Corrupt history must not be overwritten");}catch(IOException expected){}assertArrayEquals(broken,java.nio.file.Files.readAllBytes(file().toPath()));store.reset();store.save(Collections.emptyList());assertArrayEquals(before,DocumentCodec.encode(repo.load()));}
 @Test public void interruptedAtomicWriteRecoversPriorCompleteHistory()throws Exception{Note a=note(),b=a.title("New",4);DocumentHistory h=new DocumentHistory();h.record(a,b,null,1);save(new PersistentHistoryStore(context),b,h);android.util.AtomicFile atomic=new android.util.AtomicFile(file());try(FileOutputStream abandoned=atomic.startWrite()){abandoned.write("partial write".getBytes("UTF-8"));}DocumentHistory recovered=new PersistentHistoryStore(context).load(Arrays.asList(b)).get(b.id);assertNotNull(recovered);assertTrue(NoteMerge.same(a,recovered.undo(b)));}
 @Test public void oversizedHistoryIsBoundedAndNeverReplacesCurrentLibrary()throws Exception{Note a=note();NotesRepository repo=new NotesRepository(context);repo.save(Arrays.asList(a));try(RandomAccessFile out=new RandomAccessFile(file(),"rw")){out.setLength(PersistentHistoryStore.MAX_BYTES+1L);}PersistentHistoryStore store=new PersistentHistoryStore(context);assertTrue(store.load(Arrays.asList(a)).isEmpty());assertNotNull(store.notice());assertEquals(PersistentHistoryStore.MAX_BYTES+1L,file().length());assertTrue(NoteMerge.same(a,repo.load().get(0)));}
 @Test public void privateFoldersWorkWithoutStorageMigrationAndRejectDuplicatesAndPaths()throws Exception{NotesRepository repo=new NotesRepository(context);Note a=note();repo.save(Arrays.asList(a));byte[] before=DocumentCodec.encode(repo.load());repo.createFolder("Work",Arrays.asList(a));assertTrue(repo.appOnlyStorage());assertTrue(new NotesRepository(context).listFolders(Arrays.asList(a)).contains("Work"));for(String name:Arrays.asList("work","../escape","a/b"))try{repo.createFolder(name,Arrays.asList(a));fail("Unsafe/duplicate folder accepted");}catch(IOException|IllegalArgumentException expected){}assertArrayEquals(before,DocumentCodec.encode(repo.load()));}
 @Test public void onlyMostRecentSixtyFourHistoriesAreKeptWithoutDeletingNotes()throws Exception{List<Note> live=new ArrayList<>();List<PersistentHistoryStore.Entry> entries=new ArrayList<>();for(int i=0;i<70;i++){Note a=note().withId(UUID.randomUUID().toString()),b=a.title("Edited "+i,8);DocumentHistory h=new DocumentHistory();h.record(a,b,null,1);live.add(b);entries.add(new PersistentHistoryStore.Entry(b,h.snapshot()));}PersistentHistoryStore store=new PersistentHistoryStore(context);store.save(entries);Map<String,DocumentHistory> restored=new PersistentHistoryStore(context).load(live);assertEquals(64,restored.size());assertFalse(restored.containsKey(live.get(0).id));assertTrue(restored.containsKey(live.get(69).id));assertEquals(70,live.size());}
}
